import os, time, math, random, sys

DEV='/dev/robot/'
class Port:
    def __init__(self, name, mode):
        self.name=name; self.mode=mode
        if mode=='r':
            self.fd=os.open(DEV+name, os.O_RDONLY|os.O_NONBLOCK)
            self.buf=b''
        else:
            self.fd=os.open(DEV+name, os.O_WRONLY)
    def last_line(self, wait=0.5):
        # drain and return most recent complete line; block up to wait for one
        t0=time.time(); last=None
        while True:
            try:
                d=os.read(self.fd,65536)
                if d: self.buf+=d
            except BlockingIOError:
                pass
            if b'\n' in self.buf:
                lines=self.buf.split(b'\n')
                self.buf=lines[-1]
                for l in reversed(lines[:-1]):
                    if l.strip():
                        last=l.decode().strip(); break
                if last is not None:
                    return last
            if time.time()-t0>wait: return last
            time.sleep(0.02)
    def write(self, s):
        os.write(self.fd, (str(s)+'\n').encode())

class Robot:
    def __init__(self):
        self.lidar=Port('d0','r'); self.status=Port('d2','r')
        self.compass=Port('d10','r'); self.odo=Port('d7','r')
        self.rx=Port('d5','r')
        self.v=Port('d1','w'); self.w=Port('d6','w'); self.tx=Port('d3','w')
    def scan(self):
        l=self.lidar.last_line(1.0)
        if not l: return None
        try: return [float(x) for x in l.split(',')]
        except: return None
    def scan_med(self,n=3):
        ss=[]
        for _ in range(n):
            s=self.scan()
            if s and len(s)==16: ss.append(s)
            time.sleep(0.05)
        if not ss: return None
        out=[]
        for i in range(16):
            vals=sorted(v for v in (s[i] for s in ss))
            out.append(vals[len(vals)//2])
        return out
    def heading(self):
        l=self.compass.last_line(1.0)
        try: return float(l)
        except: return None
    def goal(self):
        l=self.status.last_line(1.0)
        if l and 'goal=' in l:
            return int(l.split('goal=')[1].split()[0])
        return 0
    def odom(self):
        l=self.odo.last_line(1.0)
        try: return int(l)
        except: return None
    def stop(self): self.v.write(0); self.w.write(0)
    def turn_to(self, target, tol=4, timeout=30):
        # target heading in deg
        t0=time.time()
        while time.time()-t0<timeout:
            h=self.heading()
            if h is None: continue
            err=(target-h+180)%360-180
            if abs(err)<=tol:
                self.w.write(0); return True
            rate=max(min(err*1.5,100),-100)
            if abs(rate)<8: rate=8*(1 if err>0 else -1)
            self.w.write(round(rate,1))
            time.sleep(0.1)
        self.w.write(0); return False
if __name__=='__main__':
    r=Robot()
    print('heading',r.heading()); print('goal',r.goal()); print('scan',r.scan_med())
EOF
python3 robot.py

